class Solution {public String solve(String text){ArrayList<String> prefixes=new ArrayList<>();ArrayList<Integer> counts=new ArrayList<>();String current="";int number=0;boolean pending=false;for(char c:text.toCharArray()){if(c>='0'&&c<='9'){if(!pending&&c=='0')return "INVALID";number=number*10+(c-'0');pending=true;if(number>10000)return "INVALID";}else if(c=='['){if(!pending||number<1)return "INVALID";prefixes.add(current);counts.add(number);current="";number=0;pending=false;}else if(c==']'){if(pending||counts.isEmpty())return "INVALID";int last=counts.size()-1,count=counts.remove(last);String prefix=prefixes.remove(last);if(prefix.length()+(long)current.length()*count>10000)return "INVALID";current=prefix+current.repeat(count);}else if(c>='a'&&c<='z'){if(pending)return "INVALID";current+=c;if(current.length()>10000)return "INVALID";}else return "INVALID";}return pending||!counts.isEmpty()?"INVALID":current;}}